questionvariables.text:
/* Six claims, each true at exactly three positive integers: (x - a)(x - b)(x - c) = 0 rearranged. */
trip: rand([[1,2,3],[1,2,4],[1,3,4],[2,3,4],[1,2,5],[1,3,5]]);
ra: trip[1]; rb: trip[2]; rc: trip[3];
s1: ra + rb + rc; s2: ra*rb + rb*rc + rc*ra; s3: ra*rb*rc;
lhsA: x^3 + s2*x; rhsA: s1*x^2 + s3;
tval: rb^3 + s2*rb;
ta1: tval;
ta2: 0;
/* Validation: the numerical input type rejects letters and decimals, but accepts i, inf, sets, lists, booleans and equations. This validator leaves only real numbers. */
validate_real(ex) := block([sv, fv], sv: ev(ex, simp), fv: errcatch(ev(bfloat(sv), simp)), if ratnump(sv) then "" else if is(fv = []) then "Enter a single real number, for example 3, -1/2 or sqrt(2)." else if bfloatp(first(fv)) then "" else "Enter a single real number, for example 3, -1/2 or sqrt(2).");

feedbackvariables.text:
/* Binary: the false branch is the diagnostic (a checked value offered as a counterexample). */
sx: ev(ans2, simp);
Lv: ev(sx^3 + s2*sx, simp);
Rv: ev(s1*sx^2 + s3, simp);
/* A checked value typed in a form that does not simplify exactly, such as sin(1)^2+cos(1)^2, is compared numerically. Rational values are compared exactly. */
nearA: if ratnump(sx) then false else is(abs(float(Lv - Rv)) < 10^(-9));
holdsA: is(ratsimp(radcan(Lv - Rv)) = 0) or is(nearA = true);
/* Show exact values when rational; otherwise a 2 d.p. approximation (Maxima writes 16*sqrt(2) as 2^(9/2)). */
Lrat: ratnump(Lv);
Rrat: ratnump(Rv);
